package com.yeyamo_mobile.api.partner_service.infrastructure.persistence;import jakarta.persistence.*;import java.util.UUID;@Entity@Table(name="artisan_specialties")public class ArtisanSpecialtyEntity{@Id private UUID id;@Column(nullable=false,unique=true)private String code;@Column(nullable=false)private String name;private String description;@Column(nullable=false)private boolean active;protected ArtisanSpecialtyEntity(){}public UUID getId(){return id;}public String getCode(){return code;}public String getName(){return name;}public String getDescription(){return description;}public boolean isActive(){return active;}}
